#!/usr/bin/env python3

"""
Reproduction script for the annotated types issue.
This script demonstrates the problem where annotated types are not properly 
handled in serialization_strategy configuration.
"""

from dataclasses import dataclass
from typing import Annotated
from mashumaro import DataClassDictMixin


# Define annotated types
PositiveInt = Annotated[int, "PositiveInt"]
NegativeInt = Annotated[int, "NegativeInt"]


def deserialize_positive_int(value):
    print(f"Deserializing positive int: {value}")
    if value < 0:
        raise ValueError("value < 0")
    return value


def deserialize_negative_int(value):
    print(f"Deserializing negative int: {value}")
    if value >= 0:
        raise ValueError("value >= 0")
    return value


@dataclass
class MyClass(DataClassDictMixin):
    positive_int: PositiveInt
    negative_int: NegativeInt

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "deserialize": deserialize_positive_int,
            },
            NegativeInt: {
                "deserialize": deserialize_negative_int,
            }
        }


def test_annotated_types_serialization():
    """Test that annotated types are handled correctly."""
    print("Testing annotated types serialization...")

    # This should work - creating instance manually
    try:
        obj = MyClass(positive_int=5, negative_int=-3)
        print(f"Created object: {obj}")

        # Convert to dict
        data = obj.to_dict()
        print(f"Serialized to dict: {data}")

        # Try to deserialize - this should trigger our custom deserializers
        print("\nTrying to deserialize...")
        restored_obj = MyClass.from_dict({"positive_int": 10, "negative_int": -5})
        print(f"Restored object: {restored_obj}")

    except Exception as e:
        print(f"ERROR: {e}")
        import traceback
        traceback.print_exc()


if __name__ == "__main__":
    test_annotated_types_serialization()

