from dataclasses import dataclass
from typing import Annotated
from mashumaro import DataClassDictMixin


# Define annotated types
PositiveInt = Annotated[int, "PositiveInt"]
NegativeInt = Annotated[int, "NegativeInt"]


def serialize_positive_int(value):
    print(f"[CUSTOM] Serializing positive int: {value}")
    if value < 0:
        raise ValueError("Cannot serialize negative value as PositiveInt")
    return f"POSITIVE_{value}"


def serialize_negative_int(value):
    print(f"[CUSTOM] Serializing negative int: {value}")
    if value >= 0:
        raise ValueError("Cannot serialize positive value as NegativeInt")
    return f"NEGATIVE_{value}"


@dataclass
class MyClass(DataClassDictMixin):
    positive_int: PositiveInt
    negative_int: NegativeInt

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "serialize": serialize_positive_int,
            },
            NegativeInt: {
                "serialize": serialize_negative_int,
            }
        }


def test_serialization_only():
    """Test that annotated types serialization works."""
    print("Testing annotated types SERIALIZATION only...")

    try:
        obj = MyClass(positive_int=5, negative_int=-3)
        print(f"Created object: {obj}")

        # Convert to dict - this should trigger our custom serializers
        print("\nTrying to serialize (this should use custom serializers)...")
        data = obj.to_dict()
        print(f"Serialized to dict: {data}")

        # Check if custom serializers were used
        if "POSITIVE_" in str(data.get('positive_int', '')):
            print("SUCCESS: Custom serializer for PositiveInt was used!")
        else:
            print("FAILURE: Custom serializer for PositiveInt was NOT used!")

        if "NEGATIVE_" in str(data.get('negative_int', '')):
            print("SUCCESS: Custom serializer for NegativeInt was used!")
        else:
            print("FAILURE: Custom serializer for NegativeInt was NOT used!")

    except Exception as e:
        print(f"ERROR: {e}")
        import traceback
        traceback.print_exc()


@dataclass
class RegularIntClass(DataClassDictMixin):
    positive_int: int
    negative_int: int

    class Config:
        serialization_strategy = {
            int: {
                "serialize": lambda x: f"REGULAR_INT_{x}",
            }
        }


def test_regular_int_serialization():
    """Test that regular int serialization works to compare."""
