#!/usr/bin/env python3

"""
Comprehensive test to verify that annotated types work in serialization_strategy.
This test validates the fix for distinguishing annotated types from non-annotated ones.
"""

from dataclasses import dataclass
from typing import Annotated, TypeAlias
from mashumaro import DataClassDictMixin


# Define annotated types as in the issue description
PositiveInt: TypeAlias = Annotated[int, "PositiveInt"]
NegativeInt: TypeAlias = Annotated[int, "NegativeInt"]


def deserialize_positive_int(value):
    if value < 0:
        raise ValueError("value < 0")
    return value


def deserialize_negative_int(value):
    if value >= 0:
        raise ValueError("value >= 0")
    return value


def serialize_positive_int(value):
    if value < 0:
        raise ValueError("Cannot serialize negative value as PositiveInt")
    return f"POSITIVE_{value}"


def serialize_negative_int(value):
    if value >= 0:
        raise ValueError("Cannot serialize positive value as NegativeInt")
    return f"NEGATIVE_{value}"


@dataclass
class MyClass(DataClassDictMixin):
    positive_int: PositiveInt
    negative_int: NegativeInt

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "deserialize": deserialize_positive_int,
                "serialize": serialize_positive_int,
            },
            NegativeInt: {
                "deserialize": deserialize_negative_int,
                "serialize": serialize_negative_int,
            }
        }


def test_annotated_types_both_serialize_and_deserialize():
    """Test that both serialization and deserialization work with annotated types."""
    print("Testing annotated types serialization and deserialization...")

